    m = lambda k, vi, en=None: a('m.frame.' + k, vi, en)
    m('title', 'Một frame của Recomposer: chờ việc, xin frame, animation trước, recompose, apply', 'One Recomposer frame: wait for work, request a frame, animations first, recompose, apply')
    m('overview', 'Recomposer chạy một vòng lặp trong coroutine. Chọn kịch bản: một lần ghi state từ cú bấm; một animation dùng `withFrameNanos`; hoặc animation đang chạy thì app vào nền (ON_STOP) rồi quay lại (ON_START). Theo dõi: Recomposer đang treo ở đâu, số frame, số lượt recompose, và số frame gửi cho animation.', 'The Recomposer runs a loop in a coroutine. Pick a scenario: one state write from a tap; an animation using `withFrameNanos`; or an animation running while the app goes to the background (ON_STOP) and comes back (ON_START). Watch where the Recomposer is suspended, the frame count, the recomposition count, and the frames sent to the animation.')
    m('wrapup', 'Recomposer không chạy "mỗi frame". Không có việc thì nó nằm chờ ở `awaitWorkAvailable()` và không xin frame nào. Có việc thì nó xin MỘT frame qua frame clock (trên Android là Choreographer). Trong frame đó nó làm theo thứ tự: gửi thời điểm frame cho những ai đang chờ (animation, `withFrameNanos` trong effect); rồi recompose mọi thứ bị invalidate, kể cả do animation vừa ghi; rồi apply.\nKhi app ở nền, frame clock bị tạm dừng, nên animation đứng yên.\nQuy tắc dễ nhớ: Recomposer là người làm theo ca: có việc mới vào ca, mỗi ca gom hết việc của một frame.',
      'The Recomposer does not run "every frame". With no work, it waits in `awaitWorkAvailable()` and requests no frame. With work, it requests ONE frame through the frame clock (Choreographer on Android). Within that frame it works in order: send the frame time to whoever is waiting (animations, `withFrameNanos` in effects); then recompose everything invalidated, including what the animation just wrote; then apply.\nWhile the app is in the background, the frame clock is paused, so animations stand still.\nRule of thumb: the Recomposer works in shifts: it only clocks in when there is work, and each shift handles all the work for one frame.')
    m('simp.1', 'Mã của vòng lặp được rút gọn từ Recomposer.kt @296313a4; bỏ qua movable content, xử lý lỗi, pausable composition và trace. Phần layout và draw (sau apply) thuộc Compose UI, chương B7.', 'The loop code is condensed from Recomposer.kt @296313a4; movable content, error handling, pausable composition and tracing are omitted. Layout and draw (after apply) belong to Compose UI, chapter B7.')
    m('simp.2', 'Số frame của animation (2, hoặc 3 khi có ON_STOP) và độ dời 8 mỗi frame là giả định của site; thời lượng frame tùy màn hình.', 'The number of animation frames (2, or 3 with ON_STOP) and the offset of 8 per frame are the site\'s assumptions; frame duration depends on the display.')
    m('ctl.hint', 'Chạy "một lần ghi", rồi "animation", rồi "vào nền giữa animation"; so số frame và số lượt recompose.', 'Run "one write", then "animation", then "background mid-animation"; compare frame and recomposition counts.')
    m('ctl.scenario', 'Kịch bản', 'Scenario')
    for k, vi, en in [('write', 'Một lần ghi state (bấm nút)', 'One state write (a tap)'), ('anim', 'Animation dùng withFrameNanos', 'An animation using withFrameNanos'), ('stopped', 'Vào nền giữa animation (ON_STOP → ON_START)', 'Background mid-animation (ON_STOP → ON_START)')]:
        m('ctl.scenario.' + k, vi, en)
    m('diagramTitle', 'Choreographer, frame clock, Recomposer và những gì chạy trong một frame', 'Choreographer, the frame clock, the Recomposer and what runs inside a frame')
    m('diagramDesc', 'Recomposer xin frame qua frame clock; Choreographer gọi lại; trong frame, awaiter (animation) chạy trước, rồi recompose composition và apply; lifecycle tạm dừng hoặc chạy lại frame clock', 'The Recomposer requests frames through the frame clock; Choreographer calls back; within the frame, awaiters (animations) run first, then the composition is recomposed and applied; the lifecycle pauses or resumes the frame clock')
